<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue'
import {open} from '@tauri-apps/api/dialog'
import {useRouter} from 'vue-router'
import {useSourceComparisonStore} from '@/stores/sourceComparison'
import {comparisonLabels,type ComparisonSide} from '@/types/sourceComparison'
import {libraryBytes} from '@/types/archiveLibrary'
import ComparisonRetrievalDialog from '@/components/archive/ComparisonRetrievalDialog.vue'
const comparison=useSourceComparisonStore(),router=useRouter(),dialog=ref(false)
const sides:ComparisonSide[]=['left','right']
onMounted(()=>void comparison.attach());onUnmounted(()=>comparison.detach())
watch(()=>[comparison.query,comparison.filter],()=>comparison.page=1)
watch(()=>comparison.pages,value=>comparison.page=Math.min(comparison.page,value))
async function choose(side:ComparisonSide,directory:boolean){try{const queued=import.meta.env.VITE_DESKTOP_E2E==='1'?window.__LONG_DECOMPRESS_DESKTOP_E2E__?.takeDesktopDialogSelection():undefined;const path=queued===undefined?await open({directory,multiple:false,title:`选择${side==='left'?'左侧':'右侧'}${directory?'文件夹':'ZIP'}`,filters:directory?undefined:[{name:'普通 ZIP',extensions:['zip']}]}):queued;if(typeof path==='string')await comparison.read(side,path)}catch(error){comparison.sides[side].error=String(error)}}
function goQueue(){dialog.value=false;void router.push('/decompress')}
</script>
<template>
 <div class="comparison-page custom-scrollbar" data-testid="source-comparison-page">
  <header class="page-heading"><div><span class="eyebrow">COMPARE YOUR FILES</span><h1>资料对比</h1><p class="muted">两份资料放在一起看，找到差异，再取回需要的内容。</p></div><button class="button" @click="goQueue"><i class="pi pi-list"/>查看取回任务</button></header>
  <div class="source-grid" data-testid="comparison-sources"><section v-for="side in sides" :key="side" class="source-card" :data-comparison-source="side"><div class="source-title"><h2><span>{{ side==='left'?'L':'R' }}</span>{{ side==='left'?'左侧来源':'右侧来源' }}</h2><span class="tag">{{ comparison.sides[side].source?.source.kind==='zip'?'ZIP':comparison.sides[side].source?'文件夹':'尚未选择' }}</span></div><div class="path-field"><input v-model="comparison.sides[side].path" @input="comparison.editPath(side)" :data-comparison-path="side" :disabled="comparison.busy||!!comparison.sides[side].jobId" placeholder="选择或输入文件夹 / ZIP 路径"><button class="button" :data-comparison-read="side" :disabled="comparison.busy||!!comparison.sides[side].jobId||!comparison.sides[side].path.trim()" @click="comparison.read(side,comparison.sides[side].path)">读取</button></div><div class="source-actions"><button class="button" :data-comparison-folder="side" :disabled="comparison.busy||!!comparison.sides[side].jobId" @click="choose(side,true)"><i class="pi pi-folder"/>文件夹</button><button class="button" :data-comparison-zip="side" :disabled="comparison.busy||!!comparison.sides[side].jobId" @click="choose(side,false)"><i class="pi pi-box"/>ZIP</button><button v-if="comparison.sides[side].jobId" class="link" :data-comparison-stop="side" @click="comparison.cancel(side)">停止读取</button><span class="muted">{{ comparison.sides[side].jobId?'正在读取 · '+comparison.sides[side].readCount+' 项':comparison.sides[side].source?comparison.sides[side].source!.entries.length+' 项 · 完整清单已读取':'选择固定资料进行本次对比' }}</span></div><p v-if="comparison.sides[side].error" class="error" :data-comparison-error="side" role="status">{{ comparison.sides[side].error }}</p></section></div>
  <p class="scope-note"><i class="pi pi-info-circle"/>本版查看类型、大小和时间差异，实际内容尚未核对。支持文件夹与普通 Store/Deflate ZIP；密码、分卷及其他格式可继续使用原文件浏览器。</p>
  <template v-if="comparison.ready">
   <div class="stats"><button @click="comparison.filter='left_only'"><strong>{{ comparison.counts.left_only||0 }}</strong><span>仅左侧</span></button><button @click="comparison.filter='right_only'"><strong>{{ comparison.counts.right_only||0 }}</strong><span>仅右侧</span></button><button @click="comparison.filter='changes'"><strong>{{ (comparison.counts.type||0)+(comparison.counts.size||0)+(comparison.counts.time||0) }}</strong><span>类型 / 大小 / 时间变化</span></button><button @click="comparison.filter='candidate'"><strong>{{ comparison.counts.candidate||0 }}</strong><span>内容未核对</span></button></div>
   <div class="toolbar"><input v-model="comparison.query" data-testid="comparison-search" placeholder="搜索相对路径或文件名"><select v-model="comparison.filter" data-testid="comparison-filter"><option value="all">全部条目</option><option value="changes">类型 / 大小 / 时间变化</option><option v-for="(label,kind) in comparisonLabels" :key="kind" :value="kind">{{ label }}</option></select><span class="muted">{{ comparison.filtered.length }} 项 · 每页 50 项</span></div>
   <div class="selection-bar" data-testid="comparison-selection-bar"><div><strong>已选 {{ comparison.selectedCount }} 项</strong><small>左 {{ comparison.selected.left.size }} · 右 {{ comparison.selected.right.size }}</small></div><div class="actions"><button class="button" :disabled="comparison.busy" data-testid="comparison-select-left-page" @click="comparison.togglePage('left')">勾选 / 取消本页左侧</button><button class="button" :disabled="comparison.busy" data-testid="comparison-select-right-page" @click="comparison.togglePage('right')">勾选 / 取消本页右侧</button><button class="link" :disabled="comparison.busy||!comparison.selectedCount" @click="comparison.clear">清空</button><button class="button primary" :disabled="comparison.busy||!comparison.selectedCount" data-testid="comparison-retrieve-open" @click="comparison.error='';dialog=true"><i class="pi pi-download"/>取回所选</button></div></div>
   <p v-if="comparison.error" class="error" role="alert">{{ comparison.error }}</p><p v-if="comparison.notice" class="scope-note" data-testid="comparison-notice">{{ comparison.notice }} <button class="link" @click="goQueue">前往解压中心</button></p>
   <div class="row-list" data-testid="comparison-results"><article v-for="row in comparison.visible" :key="row.path" class="comparison-row" :data-comparison-row="row.path"><button class="row-heading" :aria-expanded="comparison.expanded===row.path" :data-comparison-expand="row.path" @click="comparison.expanded=comparison.expanded===row.path?'':row.path"><strong>{{ row.path }}</strong><span class="tag" :class="{changed:!['candidate','directory'].includes(row.kind)}">{{ comparisonLabels[row.kind] }}</span><i :class="comparison.expanded===row.path?'pi pi-chevron-up':'pi pi-chevron-down'"/></button><div class="pair"><div v-for="side in sides" :key="side" class="entry" :class="{missing:!row[side]}"><label v-if="row[side]" class="entry-choice"><input type="checkbox" :checked="comparison.selected[side].has(row.path)" :disabled="comparison.busy||!row[side]!.selectable" :data-comparison-select="side+':'+row.path" :aria-label="'选择'+(side==='left'?'左侧 ':'右侧 ')+row.path" @change="comparison.toggle(side,row.path)"><i :class="row[side]!.directory?'pi pi-folder':'pi pi-file'"/><span><strong>{{ side==='left'?'左侧':'右侧' }} · {{ row[side]!.directory?'文件夹':libraryBytes(row[side]!.size) }}</strong><small>{{ row[side]!.directory?(row[side]!.selectable?'空目录，可取回':'请选择下层文件'):row[side]!.modified||'未记录时间' }}</small></span></label><p v-else>{{ side==='left'?'左侧':'右侧' }}没有这一项</p></div></div><div v-if="comparison.expanded===row.path" class="row-details" :data-comparison-details="row.path"><p>{{ row.reason }}</p><p v-for="side in sides" v-show="row[side]" :key="side" class="muted">{{ side==='left'?'左侧':'右侧' }}：{{ comparison.sides[side].source?.source.path }}{{ comparison.sides[side].source?.source.kind==='zip'?'!/':'/' }}{{ row.path }}</p></div></article><div v-if="!comparison.visible.length" class="empty"><i class="pi pi-search"/><h3>{{ comparison.rows.length?'没有符合筛选的条目':'两侧均为空' }}</h3><p class="muted">{{ comparison.rows.length?'试试其他文件名或筛选条件。':'未发现文件或子目录；不会把空清单当作内容相同证明。' }}</p></div></div>
   <footer class="pagination"><button class="button" :disabled="comparison.page<=1" data-testid="comparison-previous" @click="comparison.page--">上一页</button><span>{{ comparison.page }} / {{ comparison.pages }}</span><button class="button" :disabled="comparison.page>=comparison.pages" data-testid="comparison-next" @click="comparison.page++">下一页</button></footer>
  </template>
  <section v-else class="empty"><i class="pi pi-arrows-h"/><h3>先选择左右两份资料</h3><p class="muted">文件夹与 ZIP 可以自由组合。读取完成后，按相对路径对齐查看，并分别勾选需要保留的内容。</p></section>
  <ComparisonRetrievalDialog v-if="dialog" @close="dialog=false" @queue="goQueue"/>
 </div>
</template>
<style scoped>
.comparison-page{height:100%;overflow:auto;padding:28px 32px;min-width:0;overflow-x:hidden;background:radial-gradient(circle at 100% 0%,color-mix(in srgb,var(--dynamic-accent) 5%,transparent),transparent 45%)}.page-heading{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:3px;color:var(--dynamic-accent);font-weight:900}h1{font-size:28px;font-weight:900;margin:10px 0}h2{font-size:14px;font-weight:900;display:flex;align-items:center;gap:10px}h2 span{display:grid;place-items:center;width:28px;height:28px;border-radius:9px;background:color-mix(in srgb,var(--dynamic-accent) 10%,transparent);color:var(--dynamic-accent)}.muted{font-size:11px;line-height:1.9;color:var(--text-muted);overflow-wrap:anywhere}.button{display:inline-flex;justify-content:center;align-items:center;gap:7px;font-size:11px;border:1px solid var(--border-subtle);border-radius:10px;padding:9px 12px;background:var(--bg-input);color:var(--text-content);min-width:0}.button.primary{background:var(--dynamic-accent);color:white}.button:disabled,.link:disabled{opacity:.45}.link{font-size:11px;color:var(--dynamic-accent)}.source-grid,.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.source-card{padding:18px;border:1px solid var(--border-subtle);border-radius:16px;background:var(--bg-card);min-width:0}.source-title{display:flex;align-items:center;justify-content:space-between;gap:10px}.tag{font-size:10px;padding:4px 8px;border:1px solid var(--border-subtle);border-radius:20px;color:var(--text-muted);white-space:nowrap;flex-shrink:0}.tag.changed{color:#d97706;border-color:color-mix(in srgb,#d97706 30%,transparent);background:color-mix(in srgb,#d97706 5%,transparent)}.path-field{display:flex;gap:8px;min-width:0;margin-top:16px}.path-field input,.toolbar input,.toolbar select{min-width:0;border:1px solid var(--border-subtle);border-radius:10px;background:var(--bg-input);font-size:11px;padding:10px 12px;color:var(--text-content)}.path-field input{flex:1;width:0}.path-field button{flex-shrink:0}.source-actions,.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.source-actions{margin-top:12px}.error{font-size:11px;color:#d97706;line-height:1.9;overflow-wrap:anywhere;margin-top:12px}.scope-note{font-size:11px;line-height:1.9;color:var(--text-muted);padding:12px 16px;background:var(--bg-card);border:1px solid var(--border-subtle);border-radius:12px;margin:18px 0;overflow-wrap:anywhere}.scope-note i{color:var(--dynamic-accent);margin-right:6px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.stats button{text-align:left;padding:16px 18px;background:var(--bg-card);border:1px solid var(--border-subtle);border-radius:14px}.stats strong{display:block;font-size:22px;font-weight:900;color:var(--dynamic-accent)}.stats span{display:block;font-size:10px;line-height:1.8;color:var(--text-muted);margin-top:5px}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px}.toolbar input{flex:1;min-width:140px}.selection-bar{position:sticky;top:0;z-index:5;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:12px 16px;border-radius:12px;border:1px solid var(--border-subtle);background:var(--bg-card);margin-bottom:14px}.selection-bar strong{font-size:12px}.selection-bar small{display:block;font-size:10px;color:var(--text-muted);margin-top:5px}.comparison-row{border:1px solid var(--border-subtle);border-radius:14px;background:var(--bg-card);overflow:hidden;margin-bottom:12px;min-width:0}.row-heading{width:100%;display:flex;align-items:center;gap:12px;padding:14px 16px;text-align:left;min-width:0}.row-heading strong{flex:1;min-width:0;font-size:12px;overflow-wrap:anywhere}.row-heading>i{font-size:10px;color:var(--text-muted)}.pair{gap:0;border-top:1px solid var(--border-subtle)}.entry{padding:12px 16px;min-width:0}.entry+.entry{border-left:1px solid var(--border-subtle)}.entry-choice{display:flex;align-items:center;gap:12px;font-size:11px;min-width:0}.entry-choice>input{flex-shrink:0}.entry-choice>i{color:var(--dynamic-accent);flex-shrink:0}.entry-choice span{min-width:0}.entry-choice strong{display:block;font-size:11px;overflow-wrap:anywhere}.entry-choice small{display:block;font-size:10px;color:var(--text-muted);margin-top:6px;overflow-wrap:anywhere}.entry.missing{display:flex;align-items:center;color:var(--text-muted);font-size:11px;background:var(--bg-input)}.row-details{border-top:1px solid var(--border-subtle);padding:12px 16px;font-size:11px;line-height:1.9;overflow-wrap:anywhere}.row-details>.muted{margin-top:6px}.pagination{display:flex;gap:18px;justify-content:center;align-items:center;font-size:11px;margin:24px 0}.empty{text-align:center;padding:55px 20px}.empty>i{font-size:32px;color:var(--dynamic-accent)}.empty h3{font-size:16px;font-weight:900;margin:18px 0 10px}@media(max-width:1050px){.comparison-page{padding:22px}.source-card{padding:14px}.source-grid{gap:14px}}@media(max-width:800px){.comparison-page{padding:16px}.source-grid,.pair{grid-template-columns:minmax(0,1fr)}.entry+.entry{border-left:0;border-top:1px solid var(--border-subtle)}.stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stats button{padding:12px 14px}h1{font-size:24px}.row-heading{padding:12px;gap:8px}.entry,.row-details{padding:12px}.selection-bar{padding:12px}.actions{gap:7px}}
</style>
